```python
_USER_KEYS = ('id', 'name', 'email')


def _user_summary(u):
    """사용자 dict에서 공통 필드만 투영한다."""
    return {k: u[k] for k in _USER_KEYS}


def _select_users(users, predicate):
    """predicate를 만족하는 사용자만 골라 공통 형태로 반환한다."""
    return [_user_summary(u) for u in users if predicate(u)]


def get_active_user(users):
    return _select_users(users, lambda u: u['status'] == 'active')


def get_admin_user(users):
    return _select_users(users, lambda u: u['role'] == 'admin')
```

### 변경 포인트

