from datetime import datetime

_VALID_LEVELS = frozenset({"INFO", "WARN", "ERROR"})


def parse_log_line(s):
    """Parse 'TIMESTAMP LEVEL MSG' into a (timestamp, level, msg) tuple."""
    if not isinstance(s, str):
        raise TypeError(f"s must be str, got {type(s).__name__}")

    parts = s.split(None, 2)
    if len(parts) < 3:
        raise ValueError("line must contain TIMESTAMP, LEVEL and MSG fields")

    timestamp, level, msg = parts

    iso = timestamp[:-1] + "+00:00" if timestamp.endswith("Z") else timestamp
    try:
        datetime.fromisoformat(iso)
    except ValueError:
        raise ValueError(f"timestamp is not ISO8601: {timestamp!r}")

    if level not in _VALID_LEVELS:
        raise ValueError(f"level must be one of INFO/WARN/ERROR, got {level!r}")

    if not msg.strip():
        raise ValueError("msg must not be empty")

    return (timestamp, level, msg)
