_VALID_LEVELS = {"INFO", "WARN", "ERROR"}


def _parse_iso8601(ts: str):
    if ts.endswith("Z"):
        ts = ts[:-1] + "+00:00"
    return datetime.fromisoformat(ts)


def parse_log_line(s):
    if not isinstance(s, str):
        raise TypeError("log line must be a str")

    stripped = s.strip()
    if not stripped:
        raise ValueError("empty log line")

    parts = stripped.split(None, 2)
    if len(parts) != 3:
        raise ValueError("expected 'TIMESTAMP LEVEL MSG'")

    timestamp, level, msg = parts

    try:
        _parse_iso8601(timestamp)
    except ValueError:
        raise ValueError(f"invalid ISO8601 timestamp: {timestamp!r}")

    if level not in _VALID_LEVELS:
        raise ValueError(f"invalid log level: {level!r}")

    if not msg.strip():
        raise ValueError("empty message")

    return (timestamp, level, msg)
```

